@layer cascivo.component {
  .stat {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
    font-family: var(--cascivo-font-sans);
    min-inline-size: 0;

    /* Opt into the same chrome `@cascivo/charts`' Kpi ships, so a Stat row and a Kpi row
       in one dashboard read as one system. Kept opt-in: Stat's default is layout-only
       precisely so it can live inside a Card the app controls. */
    &[data-card] {
      padding: var(--cascivo-space-4);
      border-radius: var(--cascivo-radius-surface);
      border: 1px solid var(--cascivo-color-border);
      background: var(--cascivo-color-surface);
    }
  }

  .label {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-tight);
  }

  .value {
    font-size: var(--cascivo-text-2xl);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
    line-height: var(--cascivo-leading-tight);
    font-variant-numeric: tabular-nums;
  }

  .delta {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    font-variant-numeric: tabular-nums;

    /* Colour keys on sentiment, not direction: an error rate that rose points up and is
       bad. `data-trend` still drives the arrow. */
    &[data-sentiment='good'] {
      color: var(--cascivo-color-success-foreground);
    }

    &[data-sentiment='bad'] {
      color: var(--cascivo-color-destructive-foreground);
    }

    &[data-sentiment='neutral'] {
      color: var(--cascivo-color-text-subtle);
    }
  }

  .arrow {
    font-size: var(--cascivo-text-xs);
    line-height: 1;
  }

  .help {
    font-size: var(--cascivo-text-xs);
    color: var(--cascivo-color-text-subtle);
    line-height: var(--cascivo-leading-tight);
  }

  .visual {
    margin-block-start: var(--cascivo-space-1);
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Stat',
  description: 'Displays a key metric with optional delta, trend direction and help text',
  category: 'display',
  clientJs: 'none',
  states: [],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'card',
      description:
        "Wrap the tile in the same card chrome `@cascivo/charts`' `Kpi` ships (surface, border, radius, padding), so a `Stat` row and a `Kpi` row in one dashboard read as one system. Off by default: `Stat` is layout-only so it can sit inside a `Card` you control.",
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'label',
      nameVisibility: 'visible',
      type: 'string',
      required: true,
      description: 'What the metric measures — rendered visibly above the value.',
    },
    { name: 'value', type: 'string | number', required: true, description: 'The metric value' },
    {
      name: 'delta',
      type: 'string',
      required: false,
      description: 'Change indicator rendered next to the trend arrow',
    },
    {
      name: 'trend',
      description: "Direction of the trend indicator ('up' | 'down' | 'flat').",
      type: "'up' | 'down' | 'flat'",
      required: false,
      default: 'flat',
    },
    {
      name: 'goodDirection',
      description:
        "Which direction is *good* for this metric — the colour, independent of the arrow. 'up' (default) is the classic revenue tile; use 'down' for errors, latency, cost or churn, where a rise is bad news; 'neutral' keeps the arrow and drops the sentiment colour.",
      type: "'up' | 'down' | 'neutral'",
      required: false,
      default: 'up',
    },
    {
      name: 'helpText',
      type: 'string',
      required: false,
      description: 'Fine print below the value (methodology, time range)',
    },
    {
      name: 'visual',
      type: 'React.ReactNode',
      required: false,
      description:
        'Trailing decorative visual, e.g. a Sparkline from the separate @cascivo/charts package (not exported from @cascivo/react), rendered below the value/delta/helpText',
    },
  ],
  tokens: [
    '--cascivo-color-text',
    '--cascivo-color-text-subtle',
    '--cascivo-color-text-muted',
    '--cascivo-color-success',
    '--cascivo-color-destructive',
  ],
  accessibility: {
    role: 'none',
    wcag: '2.2-AA',
    keyboard: [],
  },
  examples: [
    { title: 'Default', code: '<Stat label="Components" value={106} />' },
    {
      title: 'With trend',
      code: '<Stat label="Bundle size" value="12.4 kB" delta="-1.2 kB" trend="up" />',
    },
    {
      title: 'With help text',
      code: '<Stat label="Axe violations" value={0} helpText="WCAG 2.1 AA, 4 app states" />',
    },
    {
      title: 'With a trailing sparkline',
      code: '<Stat label="Requests / min" value="1.2k" delta="+4.3%" trend="up" visual={<Sparkline data={requestsPerMinute} label="Requests per minute trend" />} />',
      description: 'Sparkline is from @cascivo/charts',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['stat', 'kpi', 'metric', 'number'],
  intent: {
    whenToUse: [
      'Highlighting a single key metric with a clear label',
      'Showing change over time with a delta and trend direction',
      'Annotating a metric with methodology or time-range help text',
    ],
    whenNotToUse: [
      'Multiple comparable rows of data — use DataTable',
      'A non-numeric status label — use Badge or Status',
    ],
    antiPatterns: [
      {
        bad: 'A grid of Stats used to fake a data table',
        good: 'DataTable when the values are rows to compare and sort',
        why: 'Stat optimizes for one headline number, not tabular comparison',
      },
    ],
    related: [
      {
        name: 'Card',
        relationship: 'contained-by',
        reason: 'Stats commonly sit inside a Card tile on dashboards',
      },
    ],
    a11yRationale:
      'Presentational by role; the label-value pairing is real text so the metric and its meaning are read in order, and trend direction is conveyed by text/glyph, not color alone',
    content: {
      tone: 'Factual; label names the metric, help text gives context',
      notes: 'Keep labels short; put caveats in helpText',
    },
    flexibility: [
      {
        area: 'delta and trend',
        level: 'flexible',
        note: 'Optional — include only when change is meaningful',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Trend colors must resolve to --cascivo-color-success/destructive',
      },
    ],
  },
}
